  { obligationId: 'a6', contractId: CONTRACT_ID, obligationDescription: 'Pay final retention sum of $40,000 on completion of acceptance testing', obligationType: 'Payment Milestone', owner: 'Marcus Chen', dueDate: '2026-10-07', status: 'Completed', source: 'AI Extracted', confirmationLabel: 'Confirmed', readOnly: false },
