const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:5199/contracts/11111111-1111-1111-1111-111111111111/obligations');
  await page.waitForSelector('text=Maintain 99.5% warehouse uptime SLA across all regional distribution hubs');
  const rows = await page.locator('tr', { hasText: 'Maintain 99.5%' });
  await rows.getByText('Edit').click();
  await page.waitForTimeout(200);
  await page.screenshot({ path: '.tmp-verify/actual-edit.png' });
  await browser.close();
})();
